#!/usr/bin/env -S deno run -A
import { expr, workflow } from "@david/gagen";

const releaseKind = expr("github.event.inputs.releaseKind");
const actor = expr("github.actor");

workflow({
  name: "release",
  on: {
    workflow_dispatch: {
      inputs: {
        releaseKind: {
          description: "Kind of release",
          default: "minor",
          type: "choice",
          options: ["patch", "minor"],
          required: true,
        },
      },
    },
  },
  jobs: [{
    id: "release",
    name: "release",
    runsOn: "ubuntu-latest",
    timeoutMinutes: 30,
    steps: [
      {
        name: "Clone repository",
        uses: "actions/checkout@v6",
        // pushing the tag with this token is what triggers the CI workflow that publishes
        with: { token: "${{ secrets.GH_DPRINTBOT_PAT }}" },
      },
      { uses: "denoland/setup-deno@v2" },
      {
        name: "Bump version and tag",
        run: [
          `git config user.email "${actor}@users.noreply.github.com"`,
          `git config user.name "${actor}"`,
          `deno run -A ./scripts/release.ts --${releaseKind}`,
        ],
      },
    ],
  }],
}).writeOrLint({
  filePath: new URL("./release.generated.yml", import.meta.url),
  header: "# GENERATED BY ./release.ts -- DO NOT DIRECTLY EDIT",
  pinDeps: true,
});
